customCss:
/* Custom CSS */

html,
body {
  background: transparent !important;
}

#theme-root.theme-custom {
  --river-deep: #061826;
  --river-blue: #0b5268;
  --river-teal: #00b4d8;
  --river-cyan: #00e5ff;
  --river-foam: rgba(190, 250, 255, 0.9);
  --river-glow: rgba(0, 229, 255, 0.48);
  --river-text: #ffffff;
  --river-muted: rgba(220, 248, 255, 0.68);

  width: 520px;
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 18px 22px;
  box-sizing: border-box;

  position: relative;
  overflow: hidden;

  background:
    radial-gradient(
      ellipse at 15% 120%,
      rgba(0, 180, 216, 0.28),
      transparent 48%
    ),
    radial-gradient(
      ellipse at 90% -20%,
      rgba(0, 229, 255, 0.16),
      transparent 48%
    ),
    linear-gradient(
      135deg,
      rgba(6, 24, 38, 0.92),
      rgba(5, 42, 55, 0.78),
      rgba(4, 25, 39, 0.92)
    );

  background-size: 180% 180%;

  border: 1px solid rgba(91, 226, 245, 0.28);
  border-radius: 24px;

  box-shadow:
    0 18px 45px rgba(0, 0, 0, 0.48),
    0 0 25px rgba(0, 180, 216, 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.10),
    inset 0 -1px 0 rgba(0, 229, 255, 0.10);

  backdrop-filter: blur(24px) saturate(135%);
  -webkit-backdrop-filter: blur(24px) saturate(135%);

  animation:
    riverFlow 7s ease-in-out infinite,
    riverFloat 5s ease-in-out infinite;

  isolation: isolate;
}

#theme-root.theme-custom::before {
  content: "";
  position: absolute;
  z-index: -1;
  inset: -80% -20%;

  background:
    repeating-linear-gradient(
      115deg,
      transparent 0px,
      transparent 28px,
      rgba(105, 241, 255, 0.055) 29px,
      rgba(105, 241, 255, 0.055) 31px,
      transparent 32px,
      transparent 65px
    );

  transform: translateX(-18%);
  opacity: 0.75;

  pointer-events: none;

  animation: waterCurrent 5s linear infinite;
}

#theme-root.theme-custom::after {
  content: "";
  position: absolute;
  z-index: -1;
  left: -15%;
  right: -15%;
  bottom: -32px;
  height: 70px;

  background:
    radial-gradient(
      ellipse at center,
      rgba(0, 229, 255, 0.18),
      transparent 68%
    );

  filter: blur(10px);
  pointer-events: none;

  animation: riverGlow 3.5s ease-in-out infinite alternate;
}

#theme-root.theme-custom .card-art {
  width: 84px;
  height: 84px;
  flex-shrink: 0;

  position: relative;
  overflow: hidden;

  border-radius: 16px;

  border: 1px solid rgba(190, 250, 255, 0.24);

  background:
    linear-gradient(
      145deg,
      rgba(0, 229, 255, 0.18),
      rgba(0, 60, 80, 0.4)
    );

  box-shadow:
    0 10px 24px rgba(0, 0, 0, 0.6),
    0 0 18px rgba(0, 229, 255, 0.14),
    inset 0 1px 0 rgba(255, 255, 255, 0.15);

  transform: translateZ(0);

  animation: artworkFloat 4s ease-in-out infinite;
}

#theme-root.theme-custom .card-art::after {
  content: "";
  position: absolute;
  inset: 0;

  background:
    linear-gradient(
      120deg,
      transparent 25%,
      rgba(255, 255, 255, 0.16) 48%,
      transparent 68%
    );

  background-size: 220% 100%;
  pointer-events: none;

  animation: waterReflection 4s ease-in-out infinite;
}

#theme-root.theme-custom #track-art {
  width: 100%;
  height: 100%;

  object-fit: cover;
  display: block;

  border-radius: inherit;

  filter:
    saturate(1.08)
    contrast(1.04);

  transition:
    transform 0.5s ease,
    filter 0.5s ease;
}

#theme-root.theme-custom:has(#live-pill.active) #track-art {
  transform: scale(1.035);
}

#theme-root.theme-custom .card-content {
  flex: 1;
  min-width: 0;

  display: flex;
  flex-direction: column;
  gap: 5px;

  position: relative;
  z-index: 2;
}

#theme-root.theme-custom #track-title {
  font-size: 1.15rem;
  font-weight: 700;
  line-height: 1.15;

  color: var(--river-text);

  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;

  text-shadow:
    0 2px 10px rgba(0, 0, 0, 0.8),
    0 0 14px rgba(0, 229, 255, 0.14);
}

#theme-root.theme-custom #track-artist {
  font-size: 0.85rem;
  font-weight: 500;
  line-height: 1.1;

  color: var(--river-muted);

  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

#theme-root.theme-custom .progress-container {
  width: 100%;
  height: 5px;

  position: relative;

  background: rgba(255, 255, 255, 0.10);

  border-radius: 99px;
  overflow: hidden;

  margin-top: 6px;

  box-shadow:
    inset 0 1px 3px rgba(0, 0, 0, 0.45),
    0 0 5px rgba(0, 180, 216, 0.08);
}

#theme-root.theme-custom .progress-container::after {
  content: "";
  position: absolute;
  inset: 0;

  background:
    linear-gradient(
      90deg,
      transparent,
      rgba(255, 255, 255, 0.18),
      transparent
    );

  background-size: 180px 100%;

  pointer-events: none;

  animation: progressShimmer 2.4s linear infinite;
}

#theme-root.theme-custom #progress-fill {
  height: 100%;

  background:
    linear-gradient(
      90deg,
      #007f9c 0%,
      #00b4d8 35%,
      #00e5ff 70%,
      #9af7ff 100%
    );

  border-radius: 99px;

  box-shadow:
    0 0 6px rgba(0, 229, 255, 0.8),
    0 0 12px rgba(0, 180, 216, 0.5);

  transition:
    width 0.3s linear,
    box-shadow 0.3s ease;

  position: relative;
  z-index: 1;
}

#theme-root.theme-custom .card-meta-row {
  display: flex;
  align-items: center;
  justify-content: space-between;

  width: 100%;

  margin-top: 6px;

  gap: 8px;
}

#theme-root.theme-custom #platform-badge {
  padding: 3px 8px;

  border-radius: 6px;

  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;

  background: rgba(255, 255, 255, 0.06);

  border: 1px solid rgba(190, 250, 255, 0.15);

  color: #fff;

  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.06),
    0 0 8px rgba(0, 180, 216, 0.06);
}

#theme-root.theme-custom .platform-spotify {
  border-color: rgba(30, 215, 96, 0.32);
}

#theme-root.theme-custom .platform-applemusic {
  border-color: rgba(255, 255, 255, 0.25);
}

#theme-root.theme-custom .platform-youtubemusic {
  border-color: rgba(255, 55, 55, 0.32);
}

#theme-root.theme-custom #live-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;

  padding: 3px 8px;

  border-radius: 6px;

  background: rgba(0, 0, 0, 0.48);

  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;

  border: 1px solid rgba(255, 255, 255, 0.10);

  color: rgba(255, 255, 255, 0.72);

  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

#theme-root.theme-custom #live-pill .dot {
  width: 6px;
  height: 6px;

  flex-shrink: 0;

  border-radius: 50%;

  background: rgba(180, 205, 210, 0.45);

  transition:
    background 0.3s ease,
    box-shadow 0.3s ease;
}

#theme-root.theme-custom #live-pill.active {
  border-color: rgba(0, 229, 255, 0.22);
}

#theme-root.theme-custom #live-pill.active .dot {
  background: #00e5ff;

  box-shadow:
    0 0 5px #00e5ff,
    0 0 8px #00e5ff,
    0 0 15px rgba(0, 229, 255, 0.75);

  animation: waterPulse 1.4s ease-in-out infinite;
}

#theme-root.theme-custom #timecode {
  font-family: "JetBrains Mono", "SFMono-Regular", Consolas, monospace, sans-serif;

  font-size: 0.72rem;

  color: rgba(255, 255, 255, 0.5);

  font-variant-numeric: tabular-nums;

  white-space: nowrap;
}

#theme-root.theme-custom .wave-container {
  width: 100%;
  height: 26px;

  margin-top: 2px;

  position: relative;

  overflow: hidden;

  opacity: 0.72;

  mask-image:
    linear-gradient(
      90deg,
      transparent,
      #000 8%,
      #000 92%,
      transparent
    );
  -webkit-mask-image:
    linear-gradient(
      90deg,
      transparent,
      #000 8%,
      #000 92%,
      transparent
    );
}

#theme-root.theme-custom #wave-canvas {
  width: 100%;
  height: 100%;

  display: block;

  filter:
    drop-shadow(0 0 4px rgba(0, 229, 255, 0.8))
    drop-shadow(0 0 9px rgba(0, 180, 216, 0.45));
}

#theme-root.theme-custom:has(#live-pill.active) .wave-container {
  opacity: 0.9;
}

#theme-root.theme-custom:has(#live-pill.active) .card-art {
  box-shadow:
    0 10px 24px rgba(0, 0, 0, 0.6),
    0 0 22px rgba(0, 229, 255, 0.22),
    inset 0 1px 0 rgba(255, 255, 255, 0.15);
}

#theme-root.theme-custom:has(#live-pill.active) {
  border-color: rgba(91, 226, 245, 0.38);

  box-shadow:
    0 18px 45px rgba(0, 0, 0, 0.48),
    0 0 30px rgba(0, 180, 216, 0.20),
    inset 0 1px 0 rgba(255, 255, 255, 0.11),
    inset 0 -1px 0 rgba(0, 229, 255, 0.12);
}

#theme-root.theme-custom.overlay-hidden {
  animation-play-state: paused;
}

@keyframes riverFlow {
  0% {
    background-position: 0% 50%;
  }

  50% {
    background-position: 100% 55%;
  }

  100% {
    background-position: 0% 50%;
  }
}

@keyframes riverFloat {
  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-2px);
  }
}

@keyframes waterCurrent {
  0% {
    transform: translateX(-18%) skewX(-8deg);
  }

  50% {
    transform: translateX(4%) skewX(-8deg);
  }

  100% {
    transform: translateX(-18%) skewX(-8deg);
  }
}

@keyframes riverGlow {
  0% {
    opacity: 0.35;
    transform: scaleX(0.88);
  }

  100% {
    opacity: 0.75;
    transform: scaleX(1.08);
  }
}

@keyframes artworkFloat {
  0%,
  100% {
    transform: translateY(0) rotate(0deg);
  }

  50% {
    transform: translateY(-2px) rotate(-1deg);
  }
}

@keyframes waterReflection {
  0% {
    background-position: -160% 0;
  }

  55%,
  100% {
    background-position: 160% 0;
  }
}

@keyframes progressShimmer {
  0% {
    transform: translateX(-100%);
  }

  100% {
    transform: translateX(250%);
  }
}

@keyframes waterPulse {
  0%,
  100% {
    transform: scale(0.85);
    opacity: 0.65;
  }

  50% {
    transform: scale(1.3);
    opacity: 1;
  }
}
